-- Creator tools batch 2: 216 more curated links, 2 new categories (learning, mockup & presentation).
-- Idempotent: categories use on-conflict, links are skipped when a link with the same title already exists.
-- Not featured on purpose, so the home page strip stays the same; feature any of them from Admin -> Creator tools.
insert into public.resource_categories (slug, name, sort_order)
select v.slug, v.name, (select coalesce(max(sort_order), 0) from public.resource_categories) + v.step
from (values ('learn', 'Belajar & Kursus', 10), ('mockup-present', 'Mockup & Presentasi', 20)) as v(slug, name, step)
on conflict (slug) do nothing;

