insert into public.resources (title, url, description, category_id, pricing, tags, is_featured, status, sort_order)
select v.title, v.url, v.descr, c.id, v.pricing, v.tags::text[], false, 'published',
       400 + row_number() over ()
from v
join public.resource_categories c on c.slug = v.cat
where not exists (select 1 from public.resources r where lower(r.title) = lower(v.title));
